{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_4dee58bb55c5438781c8ca464d56321f.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    @* ── Step Indicator Bar ── *@
    <nav class="step-indicator" aria-label="Application steps">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var css = step == CurrentStep ? "step active"
                    : step < CurrentStep ? "step completed"
                    : "step future";
            <button class="@css"
                    disabled="@(step >= CurrentStep)"
                    @onclick="() => GoToStep(step)">
                <span class="step-number">
                    @if (step < CurrentStep) { <span>&#10003;</span> }
                    else { @step }
                </span>
                <span class="step-label">@StepLabels[i]</span>
            </button>
            @if (i < StepLabels.Length - 1) { <span class="step-connector"></span> }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger mt-3">@_errorMessage</div>
    }

    @* ── Step 1: Personal Info ── *@
    @if (CurrentStep == 1)
    {
        <section class="step-panel">
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" />
            </div>
            <div class="step-buttons">
                <span></span>
                <button class="btn btn-primary" @onclick="NextFromPersonal" disabled="@_isValidating">
                    @if (_isValidating) { <span>Validating…</span> } else { <span>Next</span> }
                </button>
            </div>
        </section>
    }

    @* ── Step 2: Work History ── *@
    else if (CurrentStep == 2)
    {
        <section class="step-panel">
            <h4>Work History</h4>
            @for (int idx = 0; idx < _workEntries.Count; idx++)
            {
                var i = idx;
                var entry = _workEntries[i];
                <div class="card mb-3 p-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <strong>Position @(i + 1)</strong>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(i)">Remove</button>
                        }
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Company <span class="text-danger">*</span></label>
                            <input class="form-control" value="@entry.Company"
                                   @onchange="e => UpdateWork(i, entry with { Company = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input class="form-control" value="@entry.Title"
                                   @onchange="e => UpdateWork(i, entry with { Title = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-4">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input type="date" class="form-control" value="@entry.StartDate?.ToString("yyyy-MM-dd")"
                                   @onchange="e => UpdateWork(i, entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                                   disabled="@entry.IsCurrent"
                                   @onchange="e => UpdateWork(i, entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                        </div>
                        <div class="col-md-4 d-flex align-items-end mb-1">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="current-@i" checked="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(i, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = null })" />
                                <label class="form-check-label" for="current-@i">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="2" value="@entry.Description"
                                  @onchange="e => UpdateWork(i, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWork">Next</button>
            </div>
        </section>
    }

    @* ── Step 3: References ── *@
    else if (CurrentStep == 3)
    {
        <section class="step-panel">
            <h4>References</h4>
            @for (int idx = 0; idx < _references.Count; idx++)
            {
                var i = idx;
                var r = _references[i];
                <div class="card mb-3 p-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <strong>Reference @(i + 1)</strong>
                        @if (_references.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(i)">Remove</button>
                        }
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input class="form-control" value="@r.Name"
                                   @onchange="e => UpdateRef(i, r with { Name = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
                            <input class="form-control" value="@r.Relationship"
                                   @onchange="e => UpdateRef(i, r with { Relationship = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>
                    <div class="row g-2">
                        <div class="col-md-6">
                            <label class="form-label">Email <span class="text-danger">*</span></label>
                            <input type="email" class="form-control" value="@r.Email"
                                   @onchange="e => UpdateRef(i, r with { Email = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Phone <span class="text-danger">*</span></label>
                            <input type="tel" class="form-control" value="@r.Phone"
                                   @onchange="e => UpdateRef(i, r with { Phone = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }

    @* ── Step 4: Cover Letter ── *@
    else if (CurrentStep == 4)
    {
        <section class="step-panel">
            <h4>Cover Letter</h4>
            <div class="mb-2">
                <textarea class="form-control" rows="10" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"></textarea>
            </div>
            <div class="text-muted mb-3">@_coverLetter.Length / 2000 characters</div>
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="() => Advance(5)">Next</button>
            </div>
        </section>
    }

    @* ── Step 5: Review & Submit ── *@
    else if (CurrentStep == 5)
    {
        <section class="step-panel">
            <h4>Review &amp; Submit</h4>

            <div class="review-section">
                <div class="d-flex justify-content-between">
                    <h5>Personal Information</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="d-flex justify-content-between">
                    <h5>Work History</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-2 ps-2 border-start">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @entry.StartDate?.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="d-flex justify-content-between">
                    <h5>References</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                @foreach (var r in _references)
                {
                    <div class="mb-2 ps-2 border-start">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email &middot; @r.Phone</small>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="d-flex justify-content-between">
                    <h5>Cover Letter</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <p class="cover-letter-preview">@_coverLetter</p>
            </div>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting) { <span>Submitting…</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        </section>
    }

    @* ── Confirmation ── *@
    else if (CurrentStep == 6)
    {
        <section class="step-panel text-center py-5">
            <div class="mb-3" style="font-size:3rem;">&#10003;</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>@_applicationId</strong>.</p>
            <p class="text-muted">We'll review your submission and get back to you soon.</p>
        </section>
    }
