{"file_text": ".apply-container {
    max-width: 800px;
    margin: 0 auto;
}

/* ── Step Indicator ── */
.step-indicator {
    display: flex;
    align-items: center;
    gap: 0;
    margin-bottom: 1.5rem;
    padding: 1rem 0;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.25rem 0.5rem;
    flex: 0 1 auto;
    min-width: 0;
}

.step-indicator .step.completed {
    cursor: pointer;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.85rem;
    margin-bottom: 0.35rem;
    border: 2px solid #dee2e6;
    color: #adb5bd;
    background: #fff;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
    border-color: #198754;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
    color: #adb5bd;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.2rem;
}

/* ── Step Panel ── */
.step-panel {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* ── Review ── */
.review-section {
    border: 1px solid #eee;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.25rem;
    max-height: 200px;
    overflow-y: auto;
}
