+                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
+                </dl>
+            </div>
+
+            <div class="review-section">
+                <div class="d-flex justify-content-between">
+                    <h5>Work History</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(2)">Edit</button>
+                </div>
+                @foreach (var entry in _workEntries)
+                {
+                    <div class="mb-2 ps-2 border-start">
+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                        <small class="text-muted">
+                            @entry.StartDate?.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
+                        </small>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p class="mb-0 mt-1">@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="d-flex justify-content-between">
+                    <h5>References</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
+                </div>
+                @foreach (var r in _references)
+                {
+                    <div class="mb-2 ps-2 border-start">
+                        <strong>@r.Name</strong> (@r.Relationship)<br />
+                        <small>@r.Email &middot; @r.Phone</small>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="d-flex justify-content-between">
+                    <h5>Cover Letter</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => GoToStep(4)">Edit</button>
+                </div>
+                <p class="cover-letter-preview">@_coverLetter</p>
+            </div>
+
+            <div class="step-buttons">
+                <button class="btn btn-secondary" @onclick="Back">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                    @if (_isSubmitting) { <span>Submitting…</span> } else { <span>Submit Application</span> }
+                </button>
+            </div>
+        </section>
+    }
+
+    @* ── Confirmation ── *@
+    else if (CurrentStep == 6)
+    {
+        <section class="step-panel text-center py-5">
+            <div class="mb-3" style="font-size:3rem;">&#10003;</div>
+            <h3 class="text-success">Application Submitted!</h3>
+            <p class="lead">Your application ID is <strong>@_applicationId</strong>.</p>
+            <p class="text-muted">We'll review your submission and get back to you soon.</p>
+        </section>
+    }
+</div>
+
+@code {
+    private static readonly string[] StepLabels =
+        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    private int CurrentStep { get; set; } = 1;
+
+    // Step 1
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+    private bool _isValidating;
+
+    // Step 2
+    private List<WorkEntryModel> _workEntries = [new()];
+
+    // Step 3
+    private List<ReferenceModel> _references = [new()];
+
+    // Step 4
+    private string _coverLetter = string.Empty;
+
+    // Step 5
+    private bool _isSubmitting;
+    private int? _applicationId;
+
+    private string? _errorMessage;
+
+    // ── Navigation ──
+
+    private void GoToStep(int step)
+    {
+        if (step < CurrentStep)
+        {
+            _errorMessage = null;
+            CurrentStep = step;
+        }
+    }
+
+    private void Advance(int step)
+    {
+        _errorMessage = null;
+        CurrentStep = step;
+    }
+
+    private void Back() => GoToStep(CurrentStep - 1);
+
+    // ── Step 1 validation ──
+
+    private async Task NextFromPersonal()
+    {
+        _errorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
+            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        _isValidating = true;
+        try
+        {
+            var valid = await ApplicationService.ValidateEmailAsync(_email);
+            if (!valid)
+            {
+                _errorMessage = "Please enter a valid email address.";
+                return;
+            }
+            Advance(2);
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    // ── Step 2 ──
+
+    private void AddWorkEntry() => _workEntries.Add(new());
+    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
+    private void UpdateWork(int index, WorkEntryModel updated) => _workEntries[index] = updated;
+
+    private void NextFromWork()
+    {
+        _errorMessage = null;
+        foreach (var e in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate is null)
+            {
+                _errorMessage = "Each position must have a company, title, and start date.";
+                return;
+            }
+        }
+        Advance(3);
+    }
+
+    // ── Step 3 ──
+
+    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
+    private void RemoveReference(int index) => _references.RemoveAt(index);
+    private void UpdateRef(int index, ReferenceModel updated) => _references[index] = updated;
+
+    private void NextFromReferences()
+    {
+        _errorMessage = null;
+        if (_references.Count < 2)
+        {
+            _errorMessage = "Please provide at least 2 references.";
+            return;
+        }
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
+                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                _errorMessage = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+        Advance(4);
+    }
+
+    // ── Step 5: Submit ──
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = null;
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workHistory = new WorkHistory(
+                _workEntries.Select(e => new WorkEntry(
+                    e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, workHistory, refs, _coverLetter);
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            CurrentStep = 6;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    // ── View models for mutable form state ──
+
+    private record WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private record ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

toolArgs.file_text:
.apply-container {
    max-width: 800px;
    margin: 0 auto;
}

/* ── Step Indicator ── */
.step-indicator {
    display: flex;
    align-items: center;
    gap: 0;
    margin-bottom: 1.5rem;
    padding: 1rem 0;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.25rem 0.5rem;
    flex: 0 1 auto;
    min-width: 0;
}

.step-indicator .step.completed {
    cursor: pointer;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.85rem;
    margin-bottom: 0.35rem;
    border: 2px solid #dee2e6;
    color: #adb5bd;
    background: #fff;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
    border-color: #198754;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
    color: #adb5bd;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.2rem;
}

/* ── Step Panel ── */
.step-panel {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* ── Review ── */
.review-section {
    border: 1px solid #eee;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.25rem;
    max-height: 200px;
    overflow-y: auto;
}

